/* --------------------------- ST7789 彩屏驱动 --------------------------- */

#define RGB565(red, green, blue) \
    (uint16_t)((((uint16_t)(red) & 0xF8U) << 8) | \
               (((uint16_t)(green) & 0xFCU) << 3) | ((uint16_t)(blue) >> 3))

#define COLOR_BACKGROUND RGB565(5, 9, 24)
#define COLOR_PANEL      RGB565(12, 20, 43)
