#define COLOR_ACCENT     RGB565(88, 124, 255)
#define COLOR_WHITE      RGB565(239, 245, 255)
#define COLOR_MUTED      RGB565(123, 140, 177)

typedef struct {
    char character;
    uint8_t rows[7];
} glyph_t;

