_Static_assert(LOGO_WIDTH % 2 == 0, "Packed bitmap needs an even width");
_Static_assert(LOGO_WIDTH <= TFT_WIDTH && LOGO_HEIGHT <= TFT_HEIGHT,
               "Logo must fit the LCD");

static esp_err_t tft_show_njupt_logo(void)
{
    if (!s_tft_ready || s_tft_framebuffer == NULL) { return ESP_ERR_INVALID_STATE; }
    memset(s_tft_framebuffer, 0, TFT_WIDTH * TFT_HEIGHT * sizeof(uint16_t));
    const size_t left = (TFT_WIDTH - LOGO_WIDTH) / 2U;
    const size_t top = (TFT_HEIGHT - LOGO_HEIGHT) / 2U;
    for (size_t y = 0U; y < LOGO_HEIGHT; ++y) {
        for (size_t x = 0U; x < LOGO_WIDTH; ++x) {
            const uint8_t packed = s_logo_bitmap[y * LOGO_ROW_BYTES + x / 2U];
            const uint8_t alpha = (x & 1U) ? (packed & 0x0FU) : (packed >> 4);
            s_tft_framebuffer[(top + y) * TFT_WIDTH + left + x] = s_logo_palette[alpha];
        }
    }
    const esp_err_t error = tft_write_framebuffer();
    if (error == ESP_OK) {
        gpio_set_level(TFT_BL_GPIO, 1);
        ESP_LOGI(TAG, "NJUPT logo displayed, hold %u ms", (unsigned)NJUPT_LOGO_HOLD_MS);
        vTaskDelay(pdMS_TO_TICKS(NJUPT_LOGO_HOLD_MS));
    }
    return error;
}

static const uint8_t *font_rows(char character)
{
    for (size_t index = 0U; index < ARRAY_SIZE(FONT_5X7); ++index) {
        if (FONT_5X7[index].character == character) { return FONT_5X7[index].rows; }
    }
    return FONT_5X7[0].rows;
}

static void tft_fill_rect(int x, int y, int width, int height, uint16_t color)
{
    if (x < 0) { width += x; x = 0; }
    if (y < 0) { height += y; y = 0; }
    if (x + width > (int)TFT_WIDTH) { width = (int)TFT_WIDTH - x; }
    if (y + height > (int)TFT_HEIGHT) { height = (int)TFT_HEIGHT - y; }
    if (width <= 0 || height <= 0 || s_tft_framebuffer == NULL) { return; }
    for (int row = y; row < y + height; ++row) {
        for (int column = x; column < x + width; ++column) {
            s_tft_framebuffer[(size_t)row * TFT_WIDTH + (size_t)column] = color;
        }
    }
}

static void tft_draw_text(int x, int y, const char *text, uint8_t scale, uint16_t color)
{
    if (text == NULL || scale == 0U) { return; }
    while (*text != '\0') {
        const uint8_t *rows = font_rows(*text++);
        for (uint8_t row = 0U; row < 7U; ++row) {
            for (uint8_t column = 0U; column < 5U; ++column) {
                if ((rows[row] & (1U << (4U - column))) != 0U) {
                    tft_fill_rect(x + column * scale, y + row * scale,
                                  scale, scale, color);
                }
            }
        }
        x += 6 * scale;
    }
}

static void tft_draw_centered(int y, const char *text, uint8_t scale, uint16_t color)
{
    const int width = (int)strlen(text) * 6 * scale - scale;
    tft_draw_text(((int)TFT_WIDTH - width) / 2, y, text, scale, color);
}

/* “加载中”三个 16x16 点阵字，避免启动阶段依赖完整中文字库。 */
static const uint16_t LOADING_GLYPHS[3][16] = {
    {0x0800,0x0800,0x0800,0x7F7C,0x0944,0x0944,0x0944,0x1944,
     0x1144,0x1144,0x1144,0x317C,0x2344,0x6644,0x0000,0x0000},
    {0x0848,0x7F4C,0x4840,0x0840,0x7FFE,0x0840,0x7F6C,0x1028,
     0x2428,0x3F38,0x0430,0x1F30,0x747A,0x04CE,0x0404,0x0000},
    {0x0180,0x0180,0x0180,0x3FFC,0x2184,0x2184,0x2184,0x2184,
     0x3FFC,0x2184,0x0180,0x0180,0x0180,0x0180,0x0180,0x0000},
};

static void tft_draw_loading_glyphs(int y, uint8_t scale, uint16_t color)
{
    const int glyph_width = 16 * scale;
    const int gap = 4;
    const int total_width = glyph_width * 3 + gap * 2;
    const int start_x = ((int)TFT_WIDTH - total_width) / 2;
    for (int glyph = 0; glyph < 3; ++glyph) {
        for (int row = 0; row < 16; ++row) {
            for (int column = 0; column < 16; ++column) {
                if ((LOADING_GLYPHS[glyph][row] & (1U << (15 - column))) != 0U) {
                    tft_fill_rect(start_x + glyph * (glyph_width + gap) + column * scale,
                                  y + row * scale, scale, scale, color);
                }
            }
        }
    }
}

/* 校标仅由 app_main 显示一次。SD 初始化及每次重试只刷新此加载页。 */
static esp_err_t tft_show_loading(uint32_t attempt, uint32_t total_attempts)
{
    if (!s_tft_ready || s_tft_framebuffer == NULL) { return ESP_ERR_INVALID_STATE; }
    tft_fill_rect(0, 0, TFT_WIDTH, TFT_HEIGHT, COLOR_BACKGROUND);
    tft_fill_rect(12, 35, 216, 170, COLOR_PANEL);
    tft_draw_loading_glyphs(62, 2U, COLOR_WHITE);
    tft_draw_centered(108, "MICROSD CARD", 2U, COLOR_ACCENT);

    char progress[24];
    if (attempt == 0U) {
        (void)snprintf(progress, sizeof(progress), "PLEASE WAIT");
    } else {
        (void)snprintf(progress, sizeof(progress), "ATTEMPT %u / %u",
                       (unsigned)attempt, (unsigned)total_attempts);
    }
    tft_draw_centered(148, progress, 1U, COLOR_MUTED);
    tft_fill_rect(30, 178, 180, 8, COLOR_MUTED);
    if (attempt > 0U && total_attempts > 0U) {
        const int width = (int)(180U * attempt / total_attempts);
        tft_fill_rect(30, 178, width, 8, COLOR_ACCENT);
    }
    return tft_write_framebuffer();
}

/* 音乐来自 SD 卡；无文件时显示可操作的空状态。 */
static void tft_draw_song_title(uint8_t song_index)
{
    if (s_sd_wav_count == 0U) {
        tft_draw_centered(82, "NO WAV FILES", 2U, COLOR_WHITE);
        tft_draw_centered(119, "ADD WAV TO SD AND RESTART", 1U, COLOR_MUTED);
        return;
    }
    tft_draw_centered(82, "SD CARD WAV", 2U, COLOR_WHITE);
    tft_draw_centered(119, player_track_name(song_index), 1U, COLOR_MUTED);
}

static int piano_key_index(uint16_t keys)
{
    /* 普通无二极管矩阵采用单音策略：多键时静音，不产生鬼键音符。 */
    if (keys == 0U || (keys & (uint16_t)(keys - 1U)) != 0U) { return -1; }
    for (unsigned key = 0U; key < 16U; ++key) {
        if ((keys & (uint16_t)(1U << key)) != 0U) { return (int)key; }
    }
    return -1;
}

static void tft_draw_piano(const display_update_t *update)
{
    const int active = piano_key_index(update->piano_keys);
    tft_fill_rect(0, 0, TFT_WIDTH, TFT_HEIGHT, COLOR_BACKGROUND);
    tft_fill_rect(0, 0, TFT_WIDTH, 6, COLOR_NJUPT_BLUE);
    tft_draw_centered(18, "ELECTRIC PIANO", 2U, COLOR_WHITE);
    const char *state = !update->keypad_ready ? "CHECK KEYPAD WIRING" :
        (update->listening ? "LISTENING" : (update->paused ? "PAUSED" :
         (active >= 0 ? PIANO_NOTE_NAMES[active] : "PRESS A KEY")));
    tft_draw_centered(43, state, 1U, COLOR_ACCENT);
    for (unsigned key = 0U; key < 16U; ++key) {
        const int x = 14 + (int)(key % 4U) * 55;
        const int y = 65 + (int)(key / 4U) * 27;
        const bool pressed = (int)key == active && !update->paused && !update->listening;
        tft_fill_rect(x, y, 47, 23, pressed ? COLOR_ACCENT : COLOR_PANEL);
        tft_draw_text(x + 12, y + 8, PIANO_NOTE_NAMES[key], 1U, COLOR_WHITE);
    }
    char volume[24];
    (void)snprintf(volume, sizeof(volume), "VOLUME %u%%", (unsigned)update->volume_percent);
    tft_draw_centered(180, volume, 2U, COLOR_WHITE);
    tft_draw_centered(210, "HOLD BOOT: SETTINGS", 1U, COLOR_MUTED);
    tft_draw_centered(231, update->voice_ready ? "SAY NI HAO XIAO ZHI" : "VOICE OFF",
                      1U, COLOR_MUTED);
    const esp_err_t error = tft_write_framebuffer();
    if (error != ESP_OK) { ESP_LOGW(TAG, "Piano TFT refresh: %s", esp_err_to_name(error)); }
}

static void tft_draw_settings(const display_update_t *update)
{
    tft_fill_rect(0, 0, TFT_WIDTH, TFT_HEIGHT, COLOR_BACKGROUND);
    tft_fill_rect(0, 0, TFT_WIDTH, 6, COLOR_NJUPT_BLUE);
    tft_draw_centered(18, "VOLUME SETTINGS", 2U, COLOR_WHITE);
    tft_draw_centered(43, "RANGE 0 - 100%", 1U, COLOR_MUTED);
    for (unsigned item = 0U; item < 2U; ++item) {
        const int y = 61 + (int)item * 57;
        const bool selected = update->settings_target == (player_mode_t)item;
        const unsigned volume = item == 0U ? update->music_volume_percent : update->piano_volume_percent;
        char label[24];
        (void)snprintf(label, sizeof(label), "%s %u%%", item == 0U ? "MUSIC" : "PIANO", volume);
        tft_fill_rect(12, y, 216, 51, COLOR_PANEL);
        tft_fill_rect(12, y, 4, 51, selected ? COLOR_ACCENT : COLOR_MUTED);
        tft_draw_text(25, y + 8, selected ? ">" : " ", 2U, COLOR_ACCENT);
        tft_draw_text(43, y + 8, label, 2U, selected ? COLOR_WHITE : COLOR_MUTED);
        tft_fill_rect(25, y + 34, 190, 7, COLOR_BACKGROUND);
        tft_fill_rect(25, y + 34, (int)(volume * 190U / 100U), 7,
                      selected ? COLOR_ACCENT : COLOR_MUTED);
    }
    tft_draw_centered(185, "R1: MUSIC PIANO - +", 1U, COLOR_WHITE);
    tft_draw_centered(202, update->keypad_ready ? "HOLD -/+ TO REPEAT" : "CHECK KEYPAD WIRING",
                      1U, COLOR_MUTED);
    tft_draw_centered(222, "SHORT BOOT: EXIT", 1U, COLOR_ACCENT);
    const esp_err_t error = tft_write_framebuffer();
    if (error != ESP_OK) { ESP_LOGW(TAG, "Settings TFT refresh: %s", esp_err_to_name(error)); }
}

static void tft_draw_status(const display_update_t *update)
{
    if (!s_tft_ready || s_tft_framebuffer == NULL || update == NULL) {
        return;
    }
    if (update->settings_open) { tft_draw_settings(update); return; }
    if (update->mode == PLAYER_MODE_PIANO) { tft_draw_piano(update); return; }
    const uint8_t song_index = update->song_index;
    for (size_t index = 0U; index < TFT_WIDTH * TFT_HEIGHT; ++index) {
        s_tft_framebuffer[index] = COLOR_BACKGROUND;
    }

    tft_fill_rect(0, 0, TFT_WIDTH, 6, COLOR_NJUPT_BLUE);
    tft_draw_centered(18, "NOW PLAYING", 2U, COLOR_WHITE);
    const char *state = update->listening ? "LISTENING" :
                        (s_sd_wav_count == 0U && update->player_started ? "NO MUSIC" :
                        (!update->player_started ? "STARTING" :
                         (update->paused ? "PAUSED" : "PLAYING")));
    tft_draw_centered(43, state, 1U,
                      update->listening ? COLOR_ACCENT : COLOR_MUTED);

    tft_fill_rect(12, 62, 216, 85, COLOR_PANEL);
    tft_fill_rect(12, 62, 4, 85, COLOR_NJUPT_BLUE);
    tft_draw_song_title(song_index);

    char track_text[32];
    if (s_sd_wav_count > 0U) {
        (void)snprintf(track_text, sizeof(track_text), "TRACK %u/%u  WAV",
                       (unsigned)song_index + 1U, (unsigned)s_sd_wav_count);
    } else {
        (void)snprintf(track_text, sizeof(track_text), "TRACK 0/0  WAV");
    }
    tft_draw_centered(157, track_text, 1U, COLOR_MUTED);

    char volume_text[16];
    (void)snprintf(volume_text, sizeof(volume_text), "VOLUME %u%%",
                   (unsigned)update->volume_percent);
    tft_draw_centered(180, volume_text, 2U, COLOR_WHITE);

    tft_fill_rect(19, 210, 202, 14, COLOR_MUTED);
    tft_fill_rect(21, 212, 198, 10, COLOR_BACKGROUND);
    const int volume_width = (int)((update->volume_percent * 198U) / 100U);
    tft_fill_rect(21, 212, volume_width, 10,
                  update->volume_percent == 0U ? COLOR_MUTED : COLOR_ACCENT);

    tft_draw_centered(231, "HOLD BOOT: SETTINGS",
                      1U, COLOR_MUTED);

    const esp_err_t error = tft_write_framebuffer();
    if (error != ESP_OK) {
        ESP_LOGW(TAG, "TFT refresh failed: %s", esp_err_to_name(error));
    }
}

static void display_task(void *argument)
{
    (void)argument;
    display_update_t update;
    while (true) {
        if (xQueueReceive(s_display_updates, &update, portMAX_DELAY) == pdTRUE) {
            wdt_trace_set(6U);
            tft_draw_status(&update);
            wdt_trace_set(7U);
        }
    }
}

static esp_err_t tft_init(void)
{
    const gpio_config_t output_config = {
        .pin_bit_mask = (1ULL << (uint32_t)TFT_RST_GPIO) |
                        (1ULL << (uint32_t)TFT_DC_GPIO) |
                        (1ULL << (uint32_t)TFT_BL_GPIO),
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    esp_err_t error = gpio_config(&output_config);
    if (error != ESP_OK) { return error; }
    gpio_set_level(TFT_BL_GPIO, 0);

    const spi_bus_config_t bus_config = {
        .mosi_io_num = TFT_MOSI_GPIO,
        .miso_io_num = -1,
        .sclk_io_num = TFT_SCLK_GPIO,
        .quadwp_io_num = -1,
        .quadhd_io_num = -1,
        .max_transfer_sz = TFT_STREAM_PIXELS * sizeof(uint16_t),
    };
    error = spi_bus_initialize(TFT_SPI_HOST, &bus_config, SPI_DMA_CH_AUTO);
    if (error != ESP_OK) { return error; }

    const spi_device_interface_config_t device_config = {
        .clock_speed_hz = TFT_SPI_CLOCK_HZ,
        .mode = 3, /* 与已验证校标程序一致，适配无 CS 模块。 */
        .spics_io_num = -1,
        .queue_size = 1,
    };
    error = spi_bus_add_device(TFT_SPI_HOST, &device_config, &s_tft);
    if (error != ESP_OK) { return error; }

    s_tft_stream_buffer = heap_caps_malloc(TFT_STREAM_PIXELS * sizeof(uint16_t),
                                           MALLOC_CAP_DMA | MALLOC_CAP_INTERNAL);
    s_tft_framebuffer = heap_caps_malloc(TFT_WIDTH * TFT_HEIGHT * sizeof(uint16_t),
                                         MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    if (s_tft_framebuffer == NULL) {
        s_tft_framebuffer = heap_caps_malloc(TFT_WIDTH * TFT_HEIGHT * sizeof(uint16_t),
                                             MALLOC_CAP_8BIT);
    }
    if (s_tft_stream_buffer == NULL || s_tft_framebuffer == NULL) {
        return ESP_ERR_NO_MEM;
    }

    gpio_set_level(TFT_RST_GPIO, 0);
    vTaskDelay(pdMS_TO_TICKS(20));
    gpio_set_level(TFT_RST_GPIO, 1);
    vTaskDelay(pdMS_TO_TICKS(120));

    error = tft_command(0x01U, NULL, 0U); /* Software reset. */
    vTaskDelay(pdMS_TO_TICKS(150));
    if (error == ESP_OK) { error = tft_command(0x11U, NULL, 0U); } /* Sleep out. */
    vTaskDelay(pdMS_TO_TICKS(120));
    const uint8_t pixel_format = 0x55U; /* RGB565. */
    if (error == ESP_OK) { error = tft_command(0x3AU, &pixel_format, 1U); }
    const uint8_t madctl = TFT_MADCTL;
    if (error == ESP_OK) { error = tft_command(0x36U, &madctl, 1U); }
    if (error == ESP_OK) { error = tft_command(0x21U, NULL, 0U); } /* Inversion on. */
    if (error == ESP_OK) { error = tft_command(0x13U, NULL, 0U); } /* Normal mode. */
    if (error == ESP_OK) { error = tft_command(0x29U, NULL, 0U); } /* Display on. */
    vTaskDelay(pdMS_TO_TICKS(20));
    if (error == ESP_OK) {
        s_tft_ready = true;
        /* 在第一帧完整写入后再打开背光，避免显示上电杂点。 */
    }
    return error;
}

/* -------------------------- microSD 文件读取 -------------------------- */

static bool sd_build_full_path(const char *relative_path, char *full_path,
                               size_t full_path_size)
{
    if (relative_path == NULL || full_path == NULL || full_path_size == 0U ||
        relative_path[0] == '/' || strchr(relative_path, '\\') != NULL) {
        return false;
    }

    /* 拒绝空目录段、当前目录和上级目录，保证访问始终位于 /sdcard。 */
    if (relative_path[0] != '\0') {
        const char *segment = relative_path;
        while (true) {
            const char *separator = strchr(segment, '/');
            const size_t length = separator == NULL
                ? strlen(segment) : (size_t)(separator - segment);
            if (length == 0U || (length == 1U && segment[0] == '.') ||
                (length == 2U && segment[0] == '.' && segment[1] == '.')) {
                return false;
            }
            if (separator == NULL) { break; }
            segment = separator + 1;
        }
    }

    const int written = relative_path[0] == '\0'
        ? snprintf(full_path, full_path_size, "%s", SD_MOUNT_POINT)
        : snprintf(full_path, full_path_size, "%s/%s", SD_MOUNT_POINT, relative_path);
    return written >= 0 && (size_t)written < full_path_size;
}

static bool sd_path_has_wav_extension(const char *path)
{
    if (path == NULL) { return false; }
    const size_t length = strlen(path);
    if (length < 4U || path[length - 4U] != '.') { return false; }
    const char a = path[length - 3U];
    const char b = path[length - 2U];
    const char c = path[length - 1U];
    return (a == 'w' || a == 'W') && (b == 'a' || b == 'A') &&
           (c == 'v' || c == 'V');
}

static void sd_make_wav_display_name(const char *relative_path, char *name,
                                     size_t name_size)
{
    if (name == NULL || name_size == 0U) { return; }
    name[0] = '\0';
    const char *base = strrchr(relative_path, '/');
    base = base == NULL ? relative_path : base + 1;
    const size_t base_length = strlen(base);
    const size_t stem_length = base_length >= 4U ? base_length - 4U : base_length;
    size_t output = 0U;
    for (size_t index = 0U; index < stem_length && output + 1U < name_size; ++index) {
        unsigned char character = (unsigned char)base[index];
        if (character >= 'a' && character <= 'z') { character -= 'a' - 'A'; }
        if ((character >= 'A' && character <= 'Z') ||
            (character >= '0' && character <= '9') || character == '-') {
            name[output++] = (char)character;
        } else if (character == ' ' || character == '_') {
            if (output > 0U && name[output - 1U] != ' ') { name[output++] = ' '; }
        }
    }
    while (output > 0U && name[output - 1U] == ' ') { --output; }
    name[output] = '\0';
    if (output == 0U) { (void)snprintf(name, name_size, "SD CARD WAV"); }
}

static void sd_register_wav_file(const char *relative_path)
{
    if (!sd_path_has_wav_extension(relative_path)) { return; }
    if (s_sd_wav_count >= SD_MAX_WAV_FILES) {
        ESP_LOGW(TAG, "WAV list full; ignoring /%s", relative_path);
        return;
    }
    for (uint8_t index = 0U; index < s_sd_wav_count; ++index) {
        if (strcmp(s_sd_wav_files[index].relative_path, relative_path) == 0) { return; }
    }
    sd_wav_file_t *entry = &s_sd_wav_files[s_sd_wav_count];
    const int written = snprintf(entry->relative_path, sizeof(entry->relative_path),
                                 "%s", relative_path);
    if (written < 0 || (size_t)written >= sizeof(entry->relative_path)) {
        ESP_LOGW(TAG, "WAV path is too long; ignoring /%s", relative_path);
        return;
    }
    sd_make_wav_display_name(relative_path, entry->display_name,
                             sizeof(entry->display_name));
    ++s_sd_wav_count;
    ESP_LOGI(TAG, "WAV track %u registered: /%s",
             (unsigned)s_sd_wav_count, relative_path);
}

/* 从卡中读取相对路径文件。调用方决定缓冲区大小，可分块反复调用更大的文件。 */
static esp_err_t sd_card_read_file(const char *relative_path, uint8_t *buffer,
                                   size_t capacity, size_t *bytes_read)
{
    if (bytes_read != NULL) { *bytes_read = 0U; }
    if (!s_sd_mounted) { return ESP_ERR_INVALID_STATE; }
    if (relative_path == NULL || relative_path[0] == '\0' ||
        (capacity > 0U && buffer == NULL)) {
        return ESP_ERR_INVALID_ARG;
    }

    char path[SD_PATH_BUFFER_BYTES];
    if (!sd_build_full_path(relative_path, path, sizeof(path))) {
        return ESP_ERR_INVALID_ARG;
    }

    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        ESP_LOGW(TAG, "SD open failed: /%s (errno=%d)", relative_path, errno);
        return ESP_ERR_NOT_FOUND;
    }
    const size_t count = capacity == 0U ? 0U : fread(buffer, 1U, capacity, file);
    const bool failed = ferror(file) != 0;
    if (fclose(file) != 0 || failed) {
        ESP_LOGW(TAG, "SD read failed: /%s (errno=%d)", relative_path, errno);
        return ESP_FAIL;
    }
    if (bytes_read != NULL) { *bytes_read = count; }
    return ESP_OK;
}

static void sd_format_preview(const uint8_t *data, size_t size,
                              char *hex, size_t hex_size,
                              char *ascii, size_t ascii_size)
{
    size_t hex_position = 0U;
    const size_t ascii_limit = ascii_size > 0U ? ascii_size - 1U : 0U;
    for (size_t index = 0U; index < size; ++index) {
        if (hex_position + 4U <= hex_size) {
            const int written = snprintf(hex + hex_position, hex_size - hex_position,
                                         index == 0U ? "%02X" : " %02X", data[index]);
            if (written > 0) { hex_position += (size_t)written; }
        }
        if (index < ascii_limit) {
            ascii[index] = data[index] >= 32U && data[index] <= 126U
                ? (char)data[index] : '.';
        }
    }
    if (hex_size > 0U) { hex[hex_position < hex_size ? hex_position : hex_size - 1U] = '\0'; }
    if (ascii_size > 0U) { ascii[size < ascii_limit ? size : ascii_limit] = '\0'; }
}

static esp_err_t sd_scan_directory(const char *relative_directory, uint32_t depth,
                                   sd_scan_summary_t *summary)
{
    if (summary == NULL) { return ESP_ERR_INVALID_ARG; }
    char directory_path[SD_PATH_BUFFER_BYTES];
    if (!sd_build_full_path(relative_directory, directory_path, sizeof(directory_path))) {
        return ESP_ERR_INVALID_ARG;
    }

    DIR *directory = opendir(directory_path);
    if (directory == NULL) {
        ESP_LOGW(TAG, "SD directory open failed: %s (errno=%d)", directory_path, errno);
        ++summary->read_failures;
        return ESP_FAIL;
    }

    esp_err_t result = ESP_OK;
    struct dirent *entry;
    while ((entry = readdir(directory)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        if (summary->files + summary->directories >= SD_SCAN_MAX_ENTRIES) {
            summary->truncated = true;
            break;
        }

        char relative_path[SD_PATH_BUFFER_BYTES];
        const int relative_length = relative_directory[0] == '\0'
            ? snprintf(relative_path, sizeof(relative_path), "%s", entry->d_name)
            : snprintf(relative_path, sizeof(relative_path), "%s/%s",
                       relative_directory, entry->d_name);
        char full_path[SD_PATH_BUFFER_BYTES];
        if (relative_length < 0 || (size_t)relative_length >= sizeof(relative_path) ||
            !sd_build_full_path(relative_path, full_path, sizeof(full_path))) {
            ESP_LOGW(TAG, "SD path too long, skipped: %s", entry->d_name);
            ++summary->read_failures;
            continue;
        }

        struct stat information;
        if (stat(full_path, &information) != 0) {
            ESP_LOGW(TAG, "SD stat failed: /%s (errno=%d)", relative_path, errno);
            ++summary->read_failures;
            continue;
        }
        if (S_ISDIR(information.st_mode)) {
            ++summary->directories;
            ESP_LOGI(TAG, "SD directory: /%s", relative_path);
            if (depth < SD_SCAN_MAX_DEPTH) {
                const esp_err_t child_result =
                    sd_scan_directory(relative_path, depth + 1U, summary);
                if (child_result != ESP_OK) { result = child_result; }
            } else {
                summary->truncated = true;
                ESP_LOGW(TAG, "SD maximum scan depth reached at /%s", relative_path);
            }
            continue;
        }
        if (!S_ISREG(information.st_mode)) { continue; }

        ++summary->files;
        if (information.st_size > 0) {
            summary->total_bytes += (uint64_t)information.st_size;
        }
        uint8_t preview[SD_FILE_PREVIEW_BYTES];
        size_t preview_size = 0U;
        const esp_err_t read_result = sd_card_read_file(
            relative_path, preview, sizeof(preview), &preview_size);
        if (read_result == ESP_OK) {
            ++summary->readable_files;
            sd_register_wav_file(relative_path);
            char hex[SD_FILE_PREVIEW_BYTES * 3U + 1U];
            char ascii[SD_FILE_PREVIEW_BYTES + 1U];
            sd_format_preview(preview, preview_size, hex, sizeof(hex), ascii, sizeof(ascii));
            ESP_LOGI(TAG, "SD file: /%s (%lld bytes), read=%u, hex=[%s], text=[%s]",
                     relative_path, (long long)information.st_size,
                     (unsigned)preview_size, preview_size == 0U ? "empty" : hex,
                     preview_size == 0U ? "" : ascii);
        } else {
            ++summary->read_failures;
            result = read_result;
        }
    }
    if (closedir(directory) != 0) {
        ESP_LOGW(TAG, "SD directory close failed: %s (errno=%d)", directory_path, errno);
        result = ESP_FAIL;
    }
    return result;
}

/* ESP-IDF 固定以 SDMMC_FREQ_PROBING(400 kHz) 读取 CID。出现 CRC 错误时，
 * 通过此包装器把后续重试的探测时钟继续降低；正常工作时钟保持 host 配置值。
 */
static esp_err_t sd_card_set_clock(int slot, uint32_t frequency_khz)
{
    if (frequency_khz == SDMMC_FREQ_PROBING &&
        s_sd_probe_frequency_khz < frequency_khz) {
        frequency_khz = s_sd_probe_frequency_khz;
    }
    return sdspi_host_set_card_clk((sdspi_dev_handle_t)slot, frequency_khz);
}

static esp_err_t sd_card_init_and_scan_impl(void)
{
    const int sd_pins[] = {SD_MOSI_GPIO, SD_SCK_GPIO, SD_MISO_GPIO, SD_CS_GPIO};
    const int occupied_pins[] = {
        I2S_BCLK_GPIO, I2S_LRC_GPIO, I2S_DIN_GPIO, BOOT_BUTTON_GPIO,
        TFT_SCLK_GPIO, TFT_MOSI_GPIO, TFT_RST_GPIO, TFT_DC_GPIO, TFT_BL_GPIO,
        MIC_BCLK_GPIO, MIC_WS_GPIO, MIC_DATA_GPIO,
    };
    if (!GPIO_IS_VALID_OUTPUT_GPIO(SD_MOSI_GPIO) ||
        !GPIO_IS_VALID_OUTPUT_GPIO(SD_SCK_GPIO) ||
        !GPIO_IS_VALID_GPIO(SD_MISO_GPIO) ||
        !GPIO_IS_VALID_OUTPUT_GPIO(SD_CS_GPIO)) {
        return ESP_ERR_INVALID_ARG;
    }
    for (size_t index = 0U; index < ARRAY_SIZE(sd_pins); ++index) {
        for (size_t other = index + 1U; other < ARRAY_SIZE(sd_pins); ++other) {
            if (sd_pins[index] == sd_pins[other]) { return ESP_ERR_INVALID_ARG; }
        }
        for (size_t other = 0U; other < ARRAY_SIZE(occupied_pins); ++other) {
            if (sd_pins[index] == occupied_pins[other]) { return ESP_ERR_INVALID_ARG; }
        }
    }

    /* CS 在初始化之前保持高电平，避免卡在上电阶段误进入通信。 */
    const gpio_config_t cs_config = {
        .pin_bit_mask = 1ULL << (uint32_t)SD_CS_GPIO,
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_ENABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    esp_err_t error = gpio_config(&cs_config);
    if (error != ESP_OK) { return error; }
    error = gpio_set_level(SD_CS_GPIO, 1);
    if (error != ESP_OK) { return error; }

    const spi_bus_config_t bus_config = {
        .mosi_io_num = SD_MOSI_GPIO,
        .miso_io_num = SD_MISO_GPIO,
        .sclk_io_num = SD_SCK_GPIO,
        .quadwp_io_num = -1,
        .quadhd_io_num = -1,
        .max_transfer_sz = 4096,
    };
    error = spi_bus_initialize(SD_SPI_HOST, &bus_config, SPI_DMA_CH_AUTO);
    if (error != ESP_OK) { return error; }
    s_sd_bus_initialized = true;

    /* SD SPI 除时钟外的信号应保持高电平。模块未安装外部上拉时，
     * ESP32-S3 的内部上拉可防止 MISO/CMD 浮空导致初始化超时。
     */
    if ((error = gpio_set_pull_mode(SD_MOSI_GPIO, GPIO_PULLUP_ONLY)) != ESP_OK ||
        (error = gpio_set_pull_mode(SD_MISO_GPIO, GPIO_PULLUP_ONLY)) != ESP_OK ||
        (error = gpio_set_pull_mode(SD_CS_GPIO, GPIO_PULLUP_ONLY)) != ESP_OK ||
        (error = gpio_set_pull_mode(SD_SCK_GPIO, GPIO_PULLDOWN_ONLY)) != ESP_OK) {
        (void)spi_bus_free(SD_SPI_HOST);
        s_sd_bus_initialized = false;
        return error;
    }
    vTaskDelay(pdMS_TO_TICKS(50U));

    sdmmc_host_t host = SDSPI_HOST_DEFAULT();
    host.slot = SD_SPI_HOST;
    host.max_freq_khz = SD_SPI_FAST_FREQUENCY_KHZ;
    host.set_card_clk = sd_card_set_clock;
    sdspi_device_config_t slot_config = SDSPI_DEVICE_CONFIG_DEFAULT();
    slot_config.host_id = SD_SPI_HOST;
    slot_config.gpio_cs = SD_CS_GPIO;
    const esp_vfs_fat_sdmmc_mount_config_t mount_config = {
        .format_if_mount_failed = false, /* 绝不自动格式化用户的存储卡。 */
        .max_files = SD_MAX_OPEN_FILES,
        .allocation_unit_size = 16U * 1024U,
    };

    error = ESP_FAIL;
    for (uint32_t attempt = 1U; attempt <= SD_MOUNT_RETRY_COUNT; ++attempt) {
        /* CRC 错误通常来自杜邦线、模块电平转换或供电造成的信号边沿失真。
         * 前两次保留正常速度，之后逐级降速；每档尝试两次，既保证 WAV
         * 播放吞吐量，也给偶发初始化失败一次完整的重新探测机会。
         */
        const uint32_t frequency_khz = attempt <= 2U
            ? SD_SPI_FAST_FREQUENCY_KHZ
            : (attempt <= 4U ? SD_SPI_SAFE_FREQUENCY_KHZ
                             : SD_SPI_FALLBACK_FREQUENCY_KHZ);
        const uint32_t probe_frequency_khz = attempt <= 2U
            ? SD_SPI_PROBE_FAST_KHZ
            : (attempt <= 4U ? SD_SPI_PROBE_SAFE_KHZ
                             : SD_SPI_PROBE_FALLBACK_KHZ);
        s_sd_probe_frequency_khz = probe_frequency_khz;
        host.max_freq_khz = (int)frequency_khz;
        if (s_tft_ready) {
            const esp_err_t display_error =
                tft_show_loading(attempt, SD_MOUNT_RETRY_COUNT);
            if (display_error != ESP_OK) {
                ESP_LOGW(TAG, "Loading screen refresh failed: %s",
                         esp_err_to_name(display_error));
            }
        }
        ESP_LOGI(TAG,
                 "Mounting microSD attempt %u/%u: MOSI=%d SCK=%d MISO=%d CS=%d, probe=%u kHz work=%u kHz",
                 (unsigned)attempt, (unsigned)SD_MOUNT_RETRY_COUNT,
                 SD_MOSI_GPIO, SD_SCK_GPIO, SD_MISO_GPIO, SD_CS_GPIO,
                 (unsigned)probe_frequency_khz, (unsigned)frequency_khz);
        error = esp_vfs_fat_sdspi_mount(
            SD_MOUNT_POINT, &host, &slot_config, &mount_config, &s_sd_card);
        if (error == ESP_OK) { break; }
        s_sd_card = NULL;
        ESP_LOGW(TAG, "microSD attempt %u failed: %s; MISO idle=%d",
                 (unsigned)attempt, esp_err_to_name(error),
                 gpio_get_level(SD_MISO_GPIO));
        if (attempt < SD_MOUNT_RETRY_COUNT) {
            (void)gpio_set_level(SD_CS_GPIO, 1);
            vTaskDelay(pdMS_TO_TICKS(SD_MOUNT_RETRY_DELAY_MS));
        }
    }
    if (error != ESP_OK) {
        ESP_LOGE(TAG,
                 "microSD not responding: connect +5->5V, GND->GND, "
                 "CS->GPIO%d, MOSI->GPIO%d, SCK->GPIO%d, MISO->GPIO%d; last=%s",
                 SD_CS_GPIO, SD_MOSI_GPIO, SD_SCK_GPIO, SD_MISO_GPIO,
                 esp_err_to_name(error));
        (void)spi_bus_free(SD_SPI_HOST);
        s_sd_bus_initialized = false;
        s_sd_card = NULL;
        return error;
    }
    s_sd_mounted = true;
    sdmmc_card_print_info(stdout, s_sd_card);

    s_sd_wav_count = 0U;
    sd_scan_summary_t summary = {0};
    const esp_err_t scan_result = sd_scan_directory("", 0U, &summary);
    ESP_LOGI(TAG,
             "microSD scan complete: files=%u readable=%u directories=%u bytes=%llu failures=%u%s",
             (unsigned)summary.files, (unsigned)summary.readable_files,
             (unsigned)summary.directories, (unsigned long long)summary.total_bytes,
             (unsigned)summary.read_failures,
             summary.truncated ? " (limited)" : "");
    if (s_sd_wav_count > 0U) {
        s_song_index = 0U;
        ESP_LOGI(TAG, "%u WAV track(s) ready; SD playback has priority",
                 (unsigned)s_sd_wav_count);
    } else {
        ESP_LOGW(TAG, "No .wav files found; music mode stays silent");
    }
    return scan_result;
}

typedef struct {
    TaskHandle_t caller;
    esp_err_t result;
} sd_scan_task_context_t;

static void sd_card_init_and_scan_task(void *argument)
{
    sd_scan_task_context_t *context = (sd_scan_task_context_t *)argument;
    context->result = sd_card_init_and_scan_impl();
    xTaskNotifyGive(context->caller);
    vTaskDelete(NULL);
}

/* app_main 的默认栈较小，而递归扫描长文件名目录需要数 KB 临时路径空间。
 * 使用一次性的独立任务承载扫描，完成后释放其栈，不占用播放阶段的内存。
 */
static esp_err_t sd_card_init_and_scan(void)
{
    sd_scan_task_context_t context = {
        .caller = xTaskGetCurrentTaskHandle(),
        .result = ESP_FAIL,
    };
    const BaseType_t created = xTaskCreatePinnedToCore(
        sd_card_init_and_scan_task, "sd_scan", SD_SCAN_TASK_STACK_SIZE,
        &context, SD_SCAN_TASK_PRIORITY, NULL, SD_SCAN_TASK_CORE);
    if (created != pdPASS) {
        ESP_LOGE(TAG, "Cannot create SD scan task with %u-byte stack",
                 (unsigned)SD_SCAN_TASK_STACK_SIZE);
        return ESP_ERR_NO_MEM;
    }
    (void)ulTaskNotifyTake(pdTRUE, portMAX_DELAY);
    return context.result;
}

/* --------------------------- 矩阵键盘和 BOOT --------------------------- */

static bool keypad_pins_available(void)
{
    const int used[] = {
        I2S_BCLK_GPIO, I2S_LRC_GPIO, I2S_DIN_GPIO,
        TFT_SCLK_GPIO, TFT_MOSI_GPIO, TFT_RST_GPIO, TFT_DC_GPIO, TFT_BL_GPIO,
        SD_CS_GPIO, SD_MOSI_GPIO, SD_SCK_GPIO, SD_MISO_GPIO,
        MIC_BCLK_GPIO, MIC_WS_GPIO, MIC_DATA_GPIO, GPIO_NUM_43, GPIO_NUM_44,
    };
    uint64_t pins = 0U;
    for (unsigned index = 0U; index < 8U; ++index) {
        const int pin = index < 4U ? KEYPAD_COLUMNS[index] : KEYPAD_ROWS[index - 4U];
        if (!GPIO_IS_VALID_GPIO(pin) ||
            (index >= 4U && !GPIO_IS_VALID_OUTPUT_GPIO(pin)) ||
            pin == BOOT_BUTTON_GPIO) { return false; }
#if CONFIG_SPIRAM_MODE_OCT || CONFIG_ESPTOOLPY_OCT_FLASH
        /* 重配八线存储器引脚会破坏 PSRAM 访问，禁止调用 gpio_config。 */
        if (pin >= 26 && pin <= 37) { return false; }
#else
        if (pin >= 26 && pin <= 32) { return false; }
#endif
        if ((pins & (1ULL << pin)) != 0U) { return false; }
        for (unsigned occupied = 0U; occupied < sizeof(used) / sizeof(used[0]); ++occupied) {
            if (pin == used[occupied]) { return false; }
        }
        pins |= 1ULL << pin;
    }
    return true;
}

static esp_err_t button_init(void)
{
    const gpio_config_t button = {
        .pin_bit_mask = 1ULL << (uint32_t)BOOT_BUTTON_GPIO,
        .mode = GPIO_MODE_INPUT, .pull_up_en = GPIO_PULLUP_ENABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE, .intr_type = GPIO_INTR_DISABLE,
    };
    esp_err_t error = gpio_config(&button);
    if (error != ESP_OK) { return error; }
    s_button_last_raw = gpio_get_level(BOOT_BUTTON_GPIO);
    s_button_latched = s_button_last_raw == 0; /* 开机按住不触发模式切换 */
    s_button_changed_us = esp_timer_get_time();
    s_boot_next_switch_us = s_button_changed_us + BOOT_DEBOUNCE_US;
    if (!keypad_pins_available()) {
        ESP_LOGE(TAG, "Keypad disabled: GPIO conflict; GPIO0 is BOOT only, GPIO33-37 are octal memory pins.");
        return ESP_OK; /* BOOT 和播放器仍可使用，不破坏语音模型内存 */
    }
    uint64_t rows = 0U, columns = 0U;
    for (unsigned index = 0U; index < 4U; ++index) {
        rows |= 1ULL << KEYPAD_ROWS[index];
        columns |= 1ULL << KEYPAD_COLUMNS[index];
        /* 开启行输出前预置为释放状态，不输出高电平。 */
        error = gpio_set_level(KEYPAD_ROWS[index], 1);
        if (error != ESP_OK) { return error; }
    }
    const gpio_config_t column_config = {
        .pin_bit_mask = columns, .mode = GPIO_MODE_INPUT,
        .pull_up_en = GPIO_PULLUP_ENABLE, .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    const gpio_config_t row_config = {
        .pin_bit_mask = rows, .mode = GPIO_MODE_OUTPUT_OD,
        .pull_up_en = GPIO_PULLUP_DISABLE, .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    error = gpio_config(&column_config);
    if (error == ESP_OK) { error = gpio_config(&row_config); }
    s_keypad_ready = error == ESP_OK;
    return error;
}

/* 设置是独立视图，不改变播放模式；只有播放器任务修改状态。 */
static void settings_toggle(void)
{
    s_settings_open = !s_settings_open;
    if (s_settings_open) { s_settings_target = s_mode; }
    s_piano_keys = 0U;
    s_keypad_wait_release = true;
    s_settings_last_key = -1;
    display_request_update();
    ESP_LOGI(TAG, "Settings %s: MUSIC=%u%% PIANO=%u%%", s_settings_open ? "OPEN" : "CLOSED",
             (unsigned)s_volume_percent, (unsigned)s_piano_volume_percent);
}

static void button_update(int raw, int64_t now)
{
    if (raw != s_button_last_raw) {
        s_button_last_raw = raw;
        s_button_changed_us = now;
    }
    if (now - s_button_changed_us < BOOT_DEBOUNCE_US) { return; }
    if (raw == 0) {
        if (!s_button_latched) {
            s_button_latched = true;
            s_button_press_valid = now >= s_boot_next_switch_us;
            s_button_long_handled = false;
            s_button_pressed_us = s_button_changed_us;
        }
        if (s_button_press_valid && !s_button_long_handled &&
            now - s_button_pressed_us >= BOOT_SETTINGS_HOLD_US) {
            s_button_long_handled = true;
            s_boot_next_switch_us = now + BOOT_SWITCH_GUARD_US;
            settings_toggle();
        }
    } else if (s_button_latched) {
        s_button_latched = false;
        if (s_button_press_valid && !s_button_long_handled) {
            s_boot_next_switch_us = now + BOOT_SWITCH_GUARD_US;
            if (s_settings_open) { settings_toggle(); }
            else { player_apply_command(PLAYER_TOGGLE_MODE); }
        }
        s_button_press_valid = false;
    }
}

static void settings_key_apply(int key)
{
    if (key == 0 || key == 1) {
        s_settings_target = key == 0 ? PLAYER_MODE_MUSIC : PLAYER_MODE_PIANO;
    } else if (key == 2 || key == 3) {
        uint8_t *volume = s_settings_target == PLAYER_MODE_PIANO
            ? &s_piano_volume_percent : &s_volume_percent;
        uint8_t *saved = s_settings_target == PLAYER_MODE_PIANO
            ? &s_piano_saved_volume_percent : &s_saved_volume_percent;
        if ((key == 2 && *volume == 0U) || (key == 3 && *volume == 100U)) { return; }
        if (key == 2) { --*volume; }
        else { ++*volume; }
        if (*volume > 0U) { *saved = *volume; }
    } else { return; }
    display_request_update();
}

static void keypad_update(uint16_t raw, int64_t now)
{
    if (raw != s_keypad_candidate) {
        s_keypad_candidate = raw;
        s_keypad_changed_us = now;
        /* 检测到松开或多键立即取消加减连发，稳定后才接受新按键。 */
        s_settings_last_key = -1;
    }
    if (now - s_keypad_changed_us < KEYPAD_DEBOUNCE_US) { return; }
    if (s_keypad_wait_release) {
        if (raw == 0U) { s_keypad_wait_release = false; s_keypad_stable = 0U; }
        return;
    }
    if (s_settings_open) {
        s_piano_keys = 0U;
        const int key = piano_key_index(raw);
        if (key != s_settings_last_key) {
            s_settings_last_key = key;
            if (key >= 0) { settings_key_apply(key); }
            s_settings_repeat_us = now + SETTINGS_REPEAT_DELAY_US;
        } else if ((key == 2 || key == 3) && now >= s_settings_repeat_us) {
            settings_key_apply(key);
            s_settings_repeat_us = now + SETTINGS_REPEAT_INTERVAL_US;
        }
        s_keypad_stable = raw;
        return;
    }
    if (s_keypad_stable != raw || s_piano_keys != raw) {
        s_keypad_stable = raw;
        s_piano_keys = raw;
        if (s_mode == PLAYER_MODE_PIANO) { display_request_update(); }
    }
}

static void button_poll(void)
{
    const int64_t now = esp_timer_get_time();
    if (now - s_keypad_last_scan_us < KEYPAD_SCAN_INTERVAL_US) { return; }
    s_keypad_last_scan_us = now;
    /* BOOT 仅读取独立 GPIO0，矩阵列扫描不会触碰此引脚。 */
    const int boot = gpio_get_level(BOOT_BUTTON_GPIO);
    button_update(boot, now);
    if (boot == 0) { s_piano_keys = 0U; return; }
    uint16_t raw = 0U;
    if (s_keypad_ready) {
        for (unsigned row = 0U; row < 4U; ++row) {
            (void)gpio_set_level(KEYPAD_ROWS[row], 0);
            esp_rom_delay_us(10);
            for (unsigned column = 0U; column < 4U; ++column) {
                if (gpio_get_level(KEYPAD_COLUMNS[column]) == 0) {
                    raw |= (uint16_t)(1U << (row * 4U + column));
                }
            }
            (void)gpio_set_level(KEYPAD_ROWS[row], 1);
            esp_rom_delay_us(10);
        }
        if (gpio_get_level(BOOT_BUTTON_GPIO) == 0) { s_piano_keys = 0U; return; }
    }
    keypad_update(raw, now);
}

/* ------------------------------ I2S 音频 ------------------------------ */

static esp_err_t audio_init(void)
{
    i2s_chan_config_t channel_config =
        I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
    /* 音乐与电子琴共用常驻 TX 通道，避免切换时删除/重建 GDMA。
     * 6 x 256 帧约 70 ms@22.05 kHz、35 ms@44.1 kHz；总缓冲不变，
     * DMA 完成中断频率相对 128 帧描述符减半。
     */
    channel_config.dma_desc_num = AUDIO_DMA_DESC_NUM;
    channel_config.dma_frame_num = AUDIO_DMA_FRAME_NUM;
    channel_config.auto_clear = true;
    esp_err_t error = i2s_new_channel(&channel_config, &s_i2s_tx, NULL);
    if (error != ESP_OK) {
        return error;
    }

    const i2s_std_config_t standard_config = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(AUDIO_SAMPLE_RATE_HZ),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(
            I2S_DATA_BIT_WIDTH_16BIT, I2S_SLOT_MODE_STEREO),
        .gpio_cfg = {
            .mclk = I2S_GPIO_UNUSED,
            .bclk = I2S_BCLK_GPIO,
            .ws = I2S_LRC_GPIO,
            .dout = I2S_DIN_GPIO,
            .din = I2S_GPIO_UNUSED,
            .invert_flags = {
                .mclk_inv = false,
                .bclk_inv = false,
                .ws_inv = false,
            },
        },
    };
    error = i2s_channel_init_std_mode(s_i2s_tx, &standard_config);
    if (error == ESP_OK) {
        error = i2s_channel_enable(s_i2s_tx);
    }
    return error;
}

static uint32_t midi_to_frequency(uint8_t midi_note)
{
    if (midi_note < 48U || midi_note > 86U) {
        return 0U;
    }
    return MIDI_FREQUENCY_HZ[midi_note - 48U];
}

static int16_t triangle_sample(uint32_t phase, uint8_t volume_percent)
{
    const uint32_t quadrant = phase >> 30;
    const int32_t offset = (int32_t)((phase >> 15) & 0x7FFFU);
    int32_t sample;
    switch (quadrant) {
        case 0U: sample = offset; break;
        case 1U: sample = 32767 - offset; break;
        case 2U: sample = -offset; break;
        default: sample = -32768 + offset; break;
    }
    /* 电子琴全部音量档统一衰减 100 倍，百分比之间仍保持线性关系。 */
    sample = sample * (int32_t)volume_percent /
             (100 * (int32_t)PIANO_VOLUME_DIVISOR);
    return (int16_t)sample;
}

static esp_err_t audio_write_buffer(size_t frame_count)
{
    const uint8_t *position = (const uint8_t *)s_audio_buffer;
    size_t remaining = frame_count * sizeof(s_audio_buffer[0]);
    while (remaining > 0U) {
        size_t written = 0U;
        esp_err_t error = i2s_channel_write(
            s_i2s_tx, position, remaining, &written, AUDIO_WRITE_TIMEOUT_MS);
        if (error != ESP_OK) {
            return error;
        }
        if (written == 0U) {
            return ESP_FAIL;
        }
        position += written;
        remaining -= written;
    }
    button_poll();
    player_command_t command;
    while (xQueueReceive(s_player_commands, &command, 0) == pdTRUE) {
        player_apply_command(command);
    }
    return ESP_OK;
}

static uint16_t read_le16(const uint8_t *data)
{
    return (uint16_t)data[0] | ((uint16_t)data[1] << 8);
}

static uint32_t read_le32(const uint8_t *data)
{
    return (uint32_t)data[0] | ((uint32_t)data[1] << 8) |
           ((uint32_t)data[2] << 16) | ((uint32_t)data[3] << 24);
}

static esp_err_t audio_set_sample_rate(uint32_t sample_rate_hz)
{
    if (sample_rate_hz == s_audio_sample_rate_hz) { return ESP_OK; }
    if (sample_rate_hz < WAV_MIN_SAMPLE_RATE_HZ ||
        sample_rate_hz > WAV_MAX_SAMPLE_RATE_HZ) {
        return ESP_ERR_NOT_SUPPORTED;
    }
    ESP_LOGI(TAG, "I2S clock change: %lu -> %lu Hz",
             (unsigned long)s_audio_sample_rate_hz, (unsigned long)sample_rate_hz);
    esp_err_t error = i2s_channel_disable(s_i2s_tx);
    if (error != ESP_OK) { return error; }
    i2s_std_clk_config_t clock_config = I2S_STD_CLK_DEFAULT_CONFIG(sample_rate_hz);
    error = i2s_channel_reconfig_std_clock(s_i2s_tx, &clock_config);
    const esp_err_t enable_error = i2s_channel_enable(s_i2s_tx);
    if (error == ESP_OK && enable_error == ESP_OK) {
        s_audio_sample_rate_hz = sample_rate_hz;
        ESP_LOGI(TAG, "I2S clock ready: %lu Hz", (unsigned long)sample_rate_hz);
        return ESP_OK;
    }
    return error != ESP_OK ? error : enable_error;
}

static esp_err_t wav_parse_header(FILE *file, wav_stream_info_t *info)
{
    if (file == NULL || info == NULL) { return ESP_ERR_INVALID_ARG; }
    memset(info, 0, sizeof(*info));
    uint8_t riff_header[12];
    if (fread(riff_header, 1U, sizeof(riff_header), file) != sizeof(riff_header) ||
        memcmp(riff_header, "RIFF", 4U) != 0 ||
        memcmp(riff_header + 8U, "WAVE", 4U) != 0) {
        return ESP_ERR_INVALID_RESPONSE;
    }

    bool format_found = false;
    bool data_found = false;
    for (uint32_t chunk_index = 0U; chunk_index < 128U; ++chunk_index) {
        uint8_t chunk_header[8];
        if (fread(chunk_header, 1U, sizeof(chunk_header), file) != sizeof(chunk_header)) {
            break;
        }
        const uint32_t chunk_size = read_le32(chunk_header + 4U);
        const long payload_offset = ftell(file);
        if (payload_offset < 0 || chunk_size > 0x7FFFFFFEU) {
            return ESP_ERR_INVALID_SIZE;
        }

        if (memcmp(chunk_header, "fmt ", 4U) == 0) {
            if (chunk_size < 16U) { return ESP_ERR_INVALID_SIZE; }
            uint8_t format_data[40] = {0};
            const size_t read_size = chunk_size < sizeof(format_data)
                ? (size_t)chunk_size : sizeof(format_data);
            if (fread(format_data, 1U, read_size, file) != read_size) {
                return ESP_FAIL;
            }
            info->audio_format = read_le16(format_data);
            info->channels = read_le16(format_data + 2U);
            info->sample_rate_hz = read_le32(format_data + 4U);
            info->block_align = read_le16(format_data + 12U);
            info->bits_per_sample = read_le16(format_data + 14U);
            /* WAVE_FORMAT_EXTENSIBLE stores the real format at the start of its GUID. */
            if (info->audio_format == 0xFFFEU && chunk_size >= 40U) {
                info->audio_format = read_le16(format_data + 24U);
            }
            format_found = true;
        } else if (memcmp(chunk_header, "data", 4U) == 0) {
            info->data_offset = (uint32_t)payload_offset;
            info->data_size = chunk_size;
            data_found = true;
        }

        if (format_found && data_found) { break; }
        const long next_chunk = payload_offset + (long)chunk_size + (long)(chunk_size & 1U);
        if (next_chunk < payload_offset || fseek(file, next_chunk, SEEK_SET) != 0) {
            return ESP_FAIL;
        }
    }

    if (!format_found || !data_found || info->data_size == 0U ||
        (info->audio_format != 1U && info->audio_format != 3U) ||
        (info->channels != 1U && info->channels != 2U) ||
        info->sample_rate_hz < WAV_MIN_SAMPLE_RATE_HZ ||
        info->sample_rate_hz > WAV_MAX_SAMPLE_RATE_HZ) {
        return ESP_ERR_NOT_SUPPORTED;
    }
    const bool pcm_width_supported = info->audio_format == 1U &&
        (info->bits_per_sample == 8U || info->bits_per_sample == 16U ||
         info->bits_per_sample == 24U || info->bits_per_sample == 32U);
    const bool float_width_supported =
        info->audio_format == 3U && info->bits_per_sample == 32U;
    const uint16_t bytes_per_sample = (uint16_t)((info->bits_per_sample + 7U) / 8U);
    if ((!pcm_width_supported && !float_width_supported) ||
        info->block_align < info->channels * bytes_per_sample ||
        info->block_align > 8U) {
        return ESP_ERR_NOT_SUPPORTED;
    }
    return fseek(file, (long)info->data_offset, SEEK_SET) == 0 ? ESP_OK : ESP_FAIL;
}

static int16_t wav_decode_sample(const uint8_t *sample, uint16_t audio_format,
                                 uint16_t bits_per_sample)
{
    if (audio_format == 3U) {
        const uint32_t raw = read_le32(sample);
        float value = 0.0f;
        memcpy(&value, &raw, sizeof(value));
        if (value > 1.0f) { value = 1.0f; }
        if (value < -1.0f) { value = -1.0f; }
        return (int16_t)(value * 32767.0f);
    }
    switch (bits_per_sample) {
        case 8U:
            return (int16_t)(((int32_t)sample[0] - 128) << 8);
        case 16U:
            return (int16_t)read_le16(sample);
        case 24U: {
            int32_t value = (int32_t)sample[0] | ((int32_t)sample[1] << 8) |
                            ((int32_t)sample[2] << 16);
            if ((value & 0x00800000L) != 0) { value |= (int32_t)0xFF000000L; }
            return (int16_t)(value >> 8);
        }
        default:
            return (int16_t)((int32_t)read_le32(sample) >> 16);
    }
}

static esp_err_t play_sd_wav(const sd_wav_file_t *track)
{
    if (track == NULL || !s_sd_mounted) { return ESP_ERR_INVALID_STATE; }
    char path[SD_PATH_BUFFER_BYTES];
    if (!sd_build_full_path(track->relative_path, path, sizeof(path))) {
        return ESP_ERR_INVALID_ARG;
    }
    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        ESP_LOGE(TAG, "Cannot open WAV /%s (errno=%d)", track->relative_path, errno);
        return ESP_ERR_NOT_FOUND;
    }
    /* 在第一次读取之前安装较大的顺序读缓存，减少 FATFS 和 SD SPI 事务次数。 */
    if (setvbuf(file, (char *)s_wav_file_cache, _IOFBF,
                sizeof(s_wav_file_cache)) != 0) {
        ESP_LOGW(TAG, "Cannot enable WAV read cache; playback will continue");
    }

    wav_stream_info_t info;
    esp_err_t result = wav_parse_header(file, &info);
    if (result != ESP_OK) {
        ESP_LOGE(TAG, "Unsupported WAV /%s: use PCM/float, 1-2 channels, 8-96 kHz",
                 track->relative_path);
        (void)fclose(file);
        return result;
    }
    result = audio_set_sample_rate(info.sample_rate_hz);
    if (result != ESP_OK) {
        (void)fclose(file);
        return result;
    }

    const uint16_t bytes_per_sample = (uint16_t)((info.bits_per_sample + 7U) / 8U);
    const uint32_t duration_seconds = info.data_size /
        ((uint32_t)info.block_align * info.sample_rate_hz);
    ESP_LOGI(TAG, "Playing WAV /%s: %u Hz, %u ch, %u bit, %u:%02u",
             track->relative_path, (unsigned)info.sample_rate_hz,
             (unsigned)info.channels, (unsigned)info.bits_per_sample,
             (unsigned)(duration_seconds / 60U), (unsigned)(duration_seconds % 60U));

    uint8_t input[AUDIO_BUFFER_FRAMES * 8U];
    uint32_t remaining = info.data_size;
    while (remaining >= info.block_align && !s_switch_requested) {
        if (s_paused || s_listening) {
            memset(s_audio_buffer, 0, sizeof(s_audio_buffer));
            result = audio_write_buffer(AUDIO_BUFFER_FRAMES);
            if (result != ESP_OK) { break; }
            continue;
        }
        size_t frame_count = remaining / info.block_align;
        if (frame_count > AUDIO_BUFFER_FRAMES) { frame_count = AUDIO_BUFFER_FRAMES; }
        const size_t requested = frame_count * info.block_align;
        const size_t received = fread(input, 1U, requested, file);
        if (received == 0U || received % info.block_align != 0U) {
            result = ESP_FAIL;
            break;
        }
        frame_count = received / info.block_align;
        for (size_t frame = 0U; frame < frame_count; ++frame) {
            const uint8_t *source = input + frame * info.block_align;
            int32_t left = wav_decode_sample(source, info.audio_format,
                                             info.bits_per_sample);
            int32_t right = info.channels == 1U ? left :
                wav_decode_sample(source + bytes_per_sample, info.audio_format,
                                  info.bits_per_sample);
            left = left * (int32_t)s_volume_percent / 100;
            right = right * (int32_t)s_volume_percent / 100;
            s_audio_buffer[frame].left = (int16_t)left;
            s_audio_buffer[frame].right = (int16_t)right;
        }
        result = audio_write_buffer(frame_count);
        if (result != ESP_OK) { break; }
        remaining -= (uint32_t)received;
    }
    if (ferror(file) != 0 && result == ESP_OK) { result = ESP_FAIL; }
    if (fclose(file) != 0 && result == ESP_OK) { result = ESP_FAIL; }
    /* 保持 WAV 的采样率。切换到电子琴时沿用现有 I2S 时钟，避免在
     * DMA 活跃期间关闭并重配通道；下一首 WAV 如采样率不同，会在
     * 解析其文件头后由 audio_set_sample_rate() 正常调整。
     */
    return result;
}

/* 使用当前 I2S 采样率输出静音，持续轮询按键及语音队列。 */
static esp_err_t audio_silence(uint32_t duration_ms)
{
    uint32_t remaining = (uint32_t)(((uint64_t)s_audio_sample_rate_hz * duration_ms + 999U) / 1000U);
    while (remaining > 0U && !s_switch_requested) {
        const size_t batch = remaining > AUDIO_BUFFER_FRAMES ? AUDIO_BUFFER_FRAMES : remaining;
        memset(s_audio_buffer, 0, batch * sizeof(s_audio_buffer[0]));
        const esp_err_t error = audio_write_buffer(batch);
        if (error != ESP_OK) { return error; }
        remaining -= (uint32_t)batch;
    }
    return ESP_OK;
}

/* ---------------------- ESP-SR 中文离线语音识别 ---------------------- */

typedef struct {
    player_command_t command;
    const char *pinyin; /* MultiNet5 中文使用无声调、空格分隔的拼音 */
    const char *label;
} speech_command_entry_t;

static const speech_command_entry_t SPEECH_COMMANDS[] = {
    {PLAYER_NEXT, "xia yi shou", "下一首"},
    {PLAYER_PREVIOUS, "shang yi shou", "上一首"},
    {PLAYER_PAUSE, "zan ting", "暂停"},
    {PLAYER_RESUME, "ji xu", "继续"},
    {PLAYER_VOLUME_UP, "zeng da yin liang", "增大音量"},
    {PLAYER_VOLUME_DOWN, "jian xiao yin liang", "减小音量"},
    {PLAYER_MUTE, "jing yin", "静音"},
    {PLAYER_UNMUTE, "qu xiao jing yin", "取消静音"},
    {PLAYER_SONG_ONE, "bo fang di yi shou", "播放第一首"},
    {PLAYER_SONG_TWO, "bo fang di er shou", "播放第二首"},
};

static struct {
    i2s_chan_handle_t rx;
    bool rx_enabled;
    srmodel_list_t *models;
    const esp_afe_sr_iface_t *afe;
    esp_afe_sr_data_t *afe_data;
    esp_mn_iface_t *mn;
    model_iface_data_t *mn_data;
    bool commands_allocated;
    int feed_samples;
    int32_t *raw_stereo;
    int16_t *feed_mono;
    EventGroupHandle_t start_event;
    TaskHandle_t feed_task;
    TaskHandle_t detect_task;
} s_speech;

#define SPEECH_TASK_START_BIT       BIT0
#define SPEECH_TASK_RUN_BIT         BIT1
#define SPEECH_FEED_PAUSED_BIT      BIT2
#define SPEECH_DETECT_PAUSED_BIT    BIT3
#define SPEECH_ALL_PAUSED_BITS      (SPEECH_FEED_PAUSED_BIT | SPEECH_DETECT_PAUSED_BIT)

static bool speech_wait_until_active(EventBits_t paused_bit)
{
    if ((xEventGroupGetBits(s_speech.start_event) & SPEECH_TASK_RUN_BIT) != 0U) {
        return false;
    }
    xEventGroupSetBits(s_speech.start_event, paused_bit);
    xEventGroupWaitBits(s_speech.start_event, SPEECH_TASK_RUN_BIT,
                        pdFALSE, pdTRUE, portMAX_DELAY);
    xEventGroupClearBits(s_speech.start_event, paused_bit);
    return true;
}

static esp_err_t microphone_init(void)
{
    const int pins[] = {MIC_BCLK_GPIO, MIC_WS_GPIO, MIC_DATA_GPIO};
    const int occupied[] = {I2S_BCLK_GPIO, I2S_LRC_GPIO, I2S_DIN_GPIO,
                            TFT_SCLK_GPIO, TFT_MOSI_GPIO, TFT_RST_GPIO,
                            TFT_DC_GPIO, TFT_BL_GPIO, BOOT_BUTTON_GPIO,
                            SD_MOSI_GPIO, SD_SCK_GPIO, SD_MISO_GPIO, SD_CS_GPIO};
    if (!GPIO_IS_VALID_OUTPUT_GPIO(pins[0]) || !GPIO_IS_VALID_OUTPUT_GPIO(pins[1]) ||
        !GPIO_IS_VALID_GPIO(pins[2])) {
        return ESP_ERR_INVALID_ARG;
    }
    for (size_t i = 0; i < ARRAY_SIZE(pins); ++i) {
        for (size_t j = i + 1; j < ARRAY_SIZE(pins); ++j) {
            if (pins[i] == pins[j]) { return ESP_ERR_INVALID_ARG; }
        }
        for (size_t j = 0; j < ARRAY_SIZE(occupied); ++j) {
            if (pins[i] == occupied[j]) { return ESP_ERR_INVALID_ARG; }
        }
    }

    i2s_chan_config_t channel = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_1, I2S_ROLE_MASTER);
    channel.dma_desc_num = 6;
    channel.dma_frame_num = 256;
    esp_err_t error = i2s_new_channel(&channel, NULL, &s_speech.rx);
    if (error != ESP_OK) { return error; }
    const i2s_std_config_t config = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(MIC_SAMPLE_RATE_HZ),
        /* INMP441: 每帧保留两个 32-bit slot，即 64 个 BCLK；软件选 L/R。 */
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(
            I2S_DATA_BIT_WIDTH_32BIT, I2S_SLOT_MODE_STEREO),
        .gpio_cfg = {
            .mclk = I2S_GPIO_UNUSED,
            .bclk = MIC_BCLK_GPIO,
            .ws = MIC_WS_GPIO,
            .dout = I2S_GPIO_UNUSED,
            .din = MIC_DATA_GPIO,
        },
    };
    error = i2s_channel_init_std_mode(s_speech.rx, &config);
    if (error != ESP_OK) { return error; }
    error = i2s_channel_enable(s_speech.rx);
    s_speech.rx_enabled = error == ESP_OK;
    return error;
}

/* 启动失败时仅在两个任务尚未开始使用共享数据的情况下调用。 */
static void speech_cleanup_before_start(void)
{
    if (s_speech.feed_task) { vTaskDelete(s_speech.feed_task); }
    if (s_speech.detect_task) { vTaskDelete(s_speech.detect_task); }
    if (s_speech.start_event) { vEventGroupDelete(s_speech.start_event); }
    if (s_speech.commands_allocated) { (void)esp_mn_commands_free(); }
    if (s_speech.mn_data) { s_speech.mn->destroy(s_speech.mn_data); }
    if (s_speech.afe_data) { s_speech.afe->destroy(s_speech.afe_data); }
    if (s_speech.models) { esp_srmodel_deinit(s_speech.models); }
    if (s_speech.rx_enabled) { (void)i2s_channel_disable(s_speech.rx); }
    if (s_speech.rx) { (void)i2s_del_channel(s_speech.rx); }
    free(s_speech.raw_stereo);
    free(s_speech.feed_mono);
    memset(&s_speech, 0, sizeof(s_speech));
}

static void speech_feed_task(void *argument)
{
    (void)argument;
    xEventGroupWaitBits(s_speech.start_event, SPEECH_TASK_START_BIT,
                       pdFALSE, pdTRUE, portMAX_DELAY);
    const size_t frame_bytes = (size_t)s_speech.feed_samples * 2U * sizeof(int32_t);
#ifdef CONFIG_PLAYER_MIC_RIGHT_CHANNEL
    const size_t microphone_slot = 1U;
#else
    const size_t microphone_slot = 0U;
#endif
    unsigned quiet_frames = 0U;
    int64_t last_warning_us = 0;
    while (true) {
        if (speech_wait_until_active(SPEECH_FEED_PAUSED_BIT)) {
            quiet_frames = 0U;
        }
        size_t remaining = frame_bytes;
        uint8_t *destination = (uint8_t *)s_speech.raw_stereo;
        bool read_ok = true;
        while (remaining > 0U) {
            size_t received = 0U;
            const esp_err_t error = i2s_channel_read(s_speech.rx, destination,
                                                    remaining, &received,
                                                    MIC_READ_TIMEOUT_MS);
            if (error != ESP_OK || received == 0U) {
                read_ok = false;
                break;
            }
            destination += received;
            remaining -= received;
        }
        if (!read_ok) {
            if ((xEventGroupGetBits(s_speech.start_event) & SPEECH_TASK_RUN_BIT) == 0U) {
                continue;
            }
            memset(s_speech.feed_mono, 0, (size_t)s_speech.feed_samples * sizeof(int16_t));
            if (esp_timer_get_time() - last_warning_us > 5000000) {
                ESP_LOGW(TAG, "Microphone I2S read failed; check SCK/WS/SD wiring");
                last_warning_us = esp_timer_get_time();
            }
            s_speech.afe->feed(s_speech.afe_data, s_speech.feed_mono);
            vTaskDelay(pdMS_TO_TICKS(20));
            continue;
        }

        int peak = 0;
        for (int index = 0; index < s_speech.feed_samples; ++index) {
            /* INMP441 的 24-bit 数据左对齐在 32-bit slot 中，转换为 16-bit。 */
            const int16_t sample = (int16_t)(s_speech.raw_stereo[2U * index + microphone_slot] >> 16);
            s_speech.feed_mono[index] = sample;
            const int magnitude = sample < 0 ? -(int)sample : (int)sample;
            if (magnitude > peak) { peak = magnitude; }
        }
        quiet_frames = peak < 2 ? quiet_frames + 1U : 0U;
        if (quiet_frames > 100U && esp_timer_get_time() - last_warning_us > 5000000) {
            ESP_LOGW(TAG, "Microphone has almost no input; check power, SD and L/R slot");
            last_warning_us = esp_timer_get_time();
        }
        s_speech.afe->feed(s_speech.afe_data, s_speech.feed_mono);
    }
}

static void speech_finish_listening(void)
{
    s_speech.mn->clean(s_speech.mn_data);
    s_speech.afe->enable_wakenet(s_speech.afe_data);
    (void)player_post_command(PLAYER_LISTEN_END);
}

static void speech_detect_task(void *argument)
{
    (void)argument;
    xEventGroupWaitBits(s_speech.start_event, SPEECH_TASK_START_BIT,
                       pdFALSE, pdTRUE, portMAX_DELAY);
    bool listening = false;
    int64_t deadline_us = 0;
    const int expected_samples = s_speech.mn->get_samp_chunksize(s_speech.mn_data);
    int64_t last_error_us = 0;
    while (true) {
        if (speech_wait_until_active(SPEECH_DETECT_PAUSED_BIT)) {
            listening = false;
            deadline_us = 0;
        }
        afe_fetch_result_t *result = s_speech.afe->fetch_with_delay(
            s_speech.afe_data, pdMS_TO_TICKS(100));

        if ((xEventGroupGetBits(s_speech.start_event) & SPEECH_TASK_RUN_BIT) == 0U) {
            listening = false;
            continue;
        }

        /* 即使麦克风故障，命令窗口也必须在 6 秒后关闭，恢复音乐。 */
        if (listening && esp_timer_get_time() >= deadline_us) {
            listening = false;
            speech_finish_listening();
            ESP_LOGI(TAG, "Voice command window ended; waiting for wake word");
        }
        if (!result || result->ret_value == ESP_FAIL || !result->data) {
            if (esp_timer_get_time() - last_error_us > 5000000) {
                ESP_LOGW(TAG, "AFE has no valid audio frame");
                last_error_us = esp_timer_get_time();
            }
            vTaskDelay(pdMS_TO_TICKS(10));
            continue;
        }
        if (!listening && result->wakeup_state == WAKENET_DETECTED) {
            if (!player_post_command(PLAYER_LISTEN_START)) { continue; }
            s_speech.mn->clean(s_speech.mn_data);
            s_speech.afe->disable_wakenet(s_speech.afe_data);
            listening = true;
            deadline_us = esp_timer_get_time() + (int64_t)VOICE_COMMAND_TIMEOUT_MS * 1000;
            ESP_LOGI(TAG, "Wake word detected: 你好小智; say a command within 6 seconds");
            continue; /* 不将唤醒词所在帧作为命令输入。 */
        }
        if (!listening) { continue; }
        if (result->data_size != expected_samples * (int)sizeof(int16_t)) {
            ESP_LOGE(TAG, "AFE/MultiNet audio frame mismatch");
            listening = false;
            speech_finish_listening();
            continue;
        }

        /* 每帧完整输入，避免仅喂 VAD 帧破坏 MultiNet 的时间连续性。 */
        const esp_mn_state_t state = s_speech.mn->detect(s_speech.mn_data, result->data);
        if (state == ESP_MN_STATE_DETECTED) {
            esp_mn_results_t *recognized = s_speech.mn->get_results(s_speech.mn_data);
            if (recognized && recognized->num > 0 && recognized->prob[0] >= VOICE_MIN_PROBABILITY) {
                const int command_id = recognized->command_id[0];
                if (command_id >= PLAYER_NEXT && command_id <= PLAYER_SONG_TWO) {
                    ESP_LOGI(TAG, "Voice command id=%d confidence=%.2f",
                             command_id, recognized->prob[0]);
                    (void)player_post_command((player_command_t)command_id);
                    listening = false;
                    speech_finish_listening();
                }
            }
        } else if (state == ESP_MN_STATE_TIMEOUT) {
            listening = false;
            speech_finish_listening();
        }
    }
}

static esp_err_t speech_init(void)
{
#ifndef CONFIG_PLAYER_MIC_CONNECTED
    ESP_LOGI(TAG, "ESP-SR microphone disabled: no microphone connected; enable in menuconfig after wiring");
    return ESP_OK;
#endif
    esp_err_t error = microphone_init();
    if (error != ESP_OK) { goto failed; }

    s_speech.models = esp_srmodel_init("model");
    if (!s_speech.models) { error = ESP_ERR_NOT_FOUND; goto failed; }
    char *mn_name = esp_srmodel_filter(s_speech.models, "mn5", ESP_MN_CHINESE);
    char *wake_name = esp_srmodel_filter(s_speech.models, "wn9", "nihaoxiaozhi");
    if (!mn_name || !wake_name) {
        ESP_LOGE(TAG, "Required WakeNet9/MultiNet5 Chinese models missing; run full idf.py flash");
        error = ESP_ERR_NOT_FOUND;
        goto failed;
    }

    afe_config_t *config = afe_config_init("M", s_speech.models, AFE_TYPE_SR, AFE_MODE_LOW_COST);
    if (!config) { error = ESP_ERR_NO_MEM; goto failed; }
    /* 单麦克风、无播放参考信号：关闭 AEC/BSS，启用 WebRTC 降噪及 VAD。
     * 唤醒时尚无回声消除，高音量播放可能降低唤醒率，实机需要调试摆位。
     */
    config->aec_init = false;
    config->se_init = false;
    config->ns_init = true;
    config->vad_init = true;
    config->vad_delay_ms = 0; /* 每帧送入 MN，关闭 VAD 缓存截帧模式。 */
    config->wakenet_init = true;
    config->wakenet_model_name = wake_name;
    config->memory_alloc_mode = AFE_MEMORY_ALLOC_MORE_PSRAM;
    config->afe_perferred_core = 0;
    config->afe_perferred_priority = SPEECH_AFE_TASK_PRIORITY;
    s_speech.afe = esp_afe_handle_from_config(config);
    if (s_speech.afe) { s_speech.afe_data = s_speech.afe->create_from_config(config); }
    afe_config_free(config);
    if (!s_speech.afe_data) { error = ESP_ERR_NO_MEM; goto failed; }

    s_speech.mn = esp_mn_handle_from_name(mn_name);
    if (!s_speech.mn) { error = ESP_ERR_NOT_SUPPORTED; goto failed; }
    s_speech.mn_data = s_speech.mn->create(mn_name, VOICE_COMMAND_TIMEOUT_MS);
    if (!s_speech.mn_data) { error = ESP_ERR_NO_MEM; goto failed; }
    if (s_speech.afe->get_feed_channel_num(s_speech.afe_data) != 1 ||
        s_speech.mn->get_samp_rate(s_speech.mn_data) != MIC_SAMPLE_RATE_HZ ||
        s_speech.afe->get_fetch_chunksize(s_speech.afe_data) !=
            s_speech.mn->get_samp_chunksize(s_speech.mn_data)) {
        error = ESP_ERR_INVALID_SIZE;
        goto failed;
    }
    error = esp_mn_commands_alloc(s_speech.mn, s_speech.mn_data);
    if (error != ESP_OK) { goto failed; }
    s_speech.commands_allocated = true;
    for (size_t index = 0; index < ARRAY_SIZE(SPEECH_COMMANDS); ++index) {
        error = esp_mn_commands_add(SPEECH_COMMANDS[index].command, SPEECH_COMMANDS[index].pinyin);
        if (error != ESP_OK) { goto failed; }
        ESP_LOGI(TAG, "Voice command: %s", SPEECH_COMMANDS[index].label);
    }
    esp_mn_error_t *invalid_commands = esp_mn_commands_update();
    if (invalid_commands) {
        ESP_LOGE(TAG, "MultiNet rejected %d command phrases", invalid_commands->num);
        error = ESP_ERR_INVALID_ARG;
        goto failed;
    }
    s_speech.mn->set_det_threshold(s_speech.mn_data, VOICE_MIN_PROBABILITY);
    s_speech.feed_samples = s_speech.afe->get_feed_chunksize(s_speech.afe_data);
    if (s_speech.feed_samples <= 0) { error = ESP_ERR_INVALID_SIZE; goto failed; }
    s_speech.raw_stereo = heap_caps_malloc(
        (size_t)s_speech.feed_samples * 2U * sizeof(int32_t), MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
    s_speech.feed_mono = heap_caps_malloc(
        (size_t)s_speech.feed_samples * sizeof(int16_t), MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
    s_speech.start_event = xEventGroupCreate();
    if (!s_speech.raw_stereo || !s_speech.feed_mono || !s_speech.start_event) {
        error = ESP_ERR_NO_MEM;
        goto failed;
    }
    if (xTaskCreatePinnedToCore(speech_feed_task, "sr_feed", 8192, NULL,
                               SPEECH_FEED_TASK_PRIORITY, &s_speech.feed_task,
                               SPEECH_FEED_TASK_CORE) != pdPASS ||
        xTaskCreatePinnedToCore(speech_detect_task, "sr_detect", 8192, NULL,
                               SPEECH_DETECT_TASK_PRIORITY, &s_speech.detect_task,
                               SPEECH_DETECT_TASK_CORE) != pdPASS) {
        error = ESP_ERR_NO_MEM;
        goto failed;
    }
    s_speech.afe->print_pipeline(s_speech.afe_data);
    ESP_LOGI(TAG, "ESP-SR ready: %s + %s, INMP441 SCK=%d WS=%d SD=%d",
             wake_name, mn_name, MIC_BCLK_GPIO, MIC_WS_GPIO, MIC_DATA_GPIO);
    xEventGroupSetBits(s_speech.start_event,
                       SPEECH_TASK_START_BIT | SPEECH_TASK_RUN_BIT);
    return ESP_OK;

failed:
    speech_cleanup_before_start();
    return error;
}

static esp_err_t speech_set_active(bool active)
{
    if (!s_voice_ready || s_speech.start_event == NULL || s_speech.rx == NULL) {
        return ESP_OK;
    }
    if (active == s_voice_active) { return ESP_OK; }

    if (!active) {
        s_voice_active = false;
        s_listening = false;
        /* 同时清除上一次暂停留下的确认位，确保本次等待的是两个任务的新确认。 */
        xEventGroupClearBits(s_speech.start_event,
                             SPEECH_TASK_RUN_BIT | SPEECH_ALL_PAUSED_BITS);

        esp_err_t error = ESP_OK;
        if (s_speech.rx_enabled) {
            error = i2s_channel_disable(s_speech.rx);
            if (error == ESP_OK) { s_speech.rx_enabled = false; }
        }

        const EventBits_t paused = xEventGroupWaitBits(
            s_speech.start_event, SPEECH_ALL_PAUSED_BITS,
            pdFALSE, pdTRUE, pdMS_TO_TICKS(SPEECH_PAUSE_TIMEOUT_MS));
        if ((paused & SPEECH_ALL_PAUSED_BITS) == SPEECH_ALL_PAUSED_BITS) {
            s_speech.mn->clean(s_speech.mn_data);
            (void)s_speech.afe->disable_wakenet(s_speech.afe_data);
            (void)s_speech.afe->reset_buffer(s_speech.afe_data);
        } else {
            ESP_LOGW(TAG, "ESP-SR pause acknowledgement timed out: bits=0x%lx",
                     (unsigned long)paused);
        }
        ESP_LOGI(TAG, "ESP-SR paused for PIANO; microphone I2S RX=%s",
                 s_speech.rx_enabled ? "ON" : "OFF");
        return error;
    }

    const EventBits_t paused = xEventGroupWaitBits(
        s_speech.start_event, SPEECH_ALL_PAUSED_BITS,
        pdFALSE, pdTRUE, pdMS_TO_TICKS(SPEECH_PAUSE_TIMEOUT_MS));
    if ((paused & SPEECH_ALL_PAUSED_BITS) == SPEECH_ALL_PAUSED_BITS) {
        s_speech.mn->clean(s_speech.mn_data);
        (void)s_speech.afe->reset_buffer(s_speech.afe_data);
        (void)s_speech.afe->enable_wakenet(s_speech.afe_data);
    } else {
        ESP_LOGW(TAG, "ESP-SR resume without full pause acknowledgement: bits=0x%lx",
                 (unsigned long)paused);
    }

    esp_err_t error = ESP_OK;
    if (!s_speech.rx_enabled) {
        error = i2s_channel_enable(s_speech.rx);
        if (error != ESP_OK) {
            ESP_LOGE(TAG, "Cannot resume microphone I2S RX: %s", esp_err_to_name(error));
            return error;
        }
        s_speech.rx_enabled = true;
    }
    s_voice_active = true;
    xEventGroupSetBits(s_speech.start_event, SPEECH_TASK_RUN_BIT);
    ESP_LOGI(TAG, "ESP-SR resumed for MUSIC; wake word: 你好小智");
    return ESP_OK;
}

/* 常驻 TX：切换时保持当前采样率，只覆盖并排空旧音频。
 * 不在音乐/电子琴切换路径中关闭、重配或重新分配 I2S/GDMA。
 */
static esp_err_t audio_change_mode(player_mode_t mode)
{
    wdt_trace_set(1U);
    ESP_LOGI(TAG, "I2S mode prepare: %s, rate=%lu Hz",
             mode == PLAYER_MODE_PIANO ? "PIANO" : "MUSIC",
             (unsigned long)s_audio_sample_rate_hz);
    memset(s_audio_buffer, 0, sizeof(s_audio_buffer));
    /* 写过一整圈 DMA 并额外留两个描述符，确保旧歌曲片段已经送出/清空。
     * 直接写缓冲，暂停状态仍能切换。
     */
    for (unsigned batch = 0U; batch < AUDIO_DMA_DESC_NUM + 2U; ++batch) {
        const esp_err_t error = audio_write_buffer(AUDIO_DMA_FRAME_NUM);
        if (error != ESP_OK) { return error; }
    }
    ESP_LOGI(TAG, "I2S mode ready: %s; volume=%u%%",
             mode == PLAYER_MODE_PIANO ? "PIANO" : "MUSIC", (unsigned)player_current_volume());
    wdt_trace_set(2U);
    return ESP_OK;
}

static esp_err_t play_piano(void)
{
    uint32_t phase = 0U;
    uint32_t phase_step = 0U;
    uint32_t gain = 0U;
    int sounding = -1;
    wdt_trace_set(3U);
    ESP_LOGI(TAG, "Piano loop entered: rate=%lu Hz, write=%u frames, CPU%d",
             (unsigned long)s_audio_sample_rate_hz,
             (unsigned)PIANO_BUFFER_FRAMES, xPortGetCoreID());
    while (s_mode == PLAYER_MODE_PIANO) {
        button_poll();
        if (s_mode != PLAYER_MODE_PIANO) { break; }
        const int requested = s_settings_open || s_paused || s_listening ? -1 : piano_key_index(s_piano_keys);
        for (size_t frame = 0U; frame < PIANO_BUFFER_FRAMES; ++frame) {
            /* 换音前将旧音渐弱至零，再从零渐强，保持相位连续。 */
            if (requested != sounding) {
                if (gain > 0U) { --gain; }
                else {
                    sounding = requested;
                    phase = 0U;
                    phase_step = sounding < 0 ? 0U : (uint32_t)(
                        ((uint64_t)midi_to_frequency(PIANO_MIDI_NOTES[sounding]) << 32) /
                        s_audio_sample_rate_hz);
                }
            } else if (sounding >= 0 && gain < PIANO_RAMP_FRAMES) { ++gain; }
            const int16_t sample = sounding < 0 ? 0 : (int16_t)(
                (int32_t)triangle_sample(phase, s_piano_volume_percent) * (int32_t)gain / PIANO_RAMP_FRAMES);
            s_audio_buffer[frame].left = sample;
            s_audio_buffer[frame].right = sample;
            phase += phase_step;
        }
        wdt_trace_set(4U);
        const esp_err_t error = audio_write_buffer(PIANO_BUFFER_FRAMES);
        if (error != ESP_OK) { return error; }
        wdt_trace_set(5U);
    }
    return ESP_OK;
}

static void player_task(void *argument)
{
    (void)argument;
    /* i2s_new_channel() 会把 GDMA 中断分配到调用它的 CPU。播放器固定在
     * CPU1，因此在这里初始化 TX，避免 CPU1 写队列、CPU0 ISR 高频唤醒
     * 造成的跨核压力。INMP441 的 I2S1 RX 仍由 CPU0 上的语音任务使用。
     */
    ESP_LOGI(TAG, "Initializing MAX98357 I2S TX on CPU%d", xPortGetCoreID());
    const esp_err_t audio_error = audio_init();
    if (audio_error != ESP_OK) {
        ESP_LOGE(TAG, "Cannot initialize MAX98357 I2S: %s", esp_err_to_name(audio_error));
        vTaskDelete(NULL);
        return;
    }
    s_player_started = true;
    player_mode_t audio_mode = PLAYER_MODE_MUSIC;
    while (true) {
        if (audio_mode != s_mode) {
            const esp_err_t speech_error = speech_set_active(s_mode == PLAYER_MODE_MUSIC);
            if (speech_error != ESP_OK) {
                ESP_LOGW(TAG, "ESP-SR mode change: %s", esp_err_to_name(speech_error));
            }
            const esp_err_t mode_error = audio_change_mode(s_mode);
            if (mode_error != ESP_OK) {
                ESP_LOGE(TAG, "Cannot switch I2S mode: %s", esp_err_to_name(mode_error));
                vTaskDelete(NULL);
                return;
            }
            audio_mode = s_mode;
        }
        s_switch_requested = false;
        display_request_update();
        if (s_mode == PLAYER_MODE_PIANO) {
            const esp_err_t piano_error = play_piano();
            if (piano_error != ESP_OK) {
                ESP_LOGE(TAG, "Piano audio: %s", esp_err_to_name(piano_error));
                vTaskDelay(pdMS_TO_TICKS(100));
            }
            continue;
        }
        esp_err_t error;
        if (s_sd_wav_count > 0U) {
            ESP_LOGI(TAG, "Playing SD track %u/%u: %s",
                     (unsigned)(s_song_index + 1U), (unsigned)s_sd_wav_count,
                     s_sd_wav_files[s_song_index].relative_path);
            error = play_sd_wav(&s_sd_wav_files[s_song_index]);
        } else {
            /* 无 SD/WAV 时保持静音，设置和模式切换仍可使用。 */
            while (s_mode == PLAYER_MODE_MUSIC && s_sd_wav_count == 0U) {
                s_switch_requested = false;
                error = audio_silence(100U);
                if (error != ESP_OK) { vTaskDelay(pdMS_TO_TICKS(100)); }
            }
            continue;
        }
        if (error != ESP_OK) {
            ESP_LOGE(TAG, "Playback error: %s", esp_err_to_name(error));
            vTaskDelay(pdMS_TO_TICKS(500));
        }

        if (s_mode != PLAYER_MODE_MUSIC) { continue; }
        if (!s_switch_requested) {
            /* 自然播放完毕后停顿半秒，然后循环当前歌曲。 */
            (void)audio_silence(500U);
        } else {
            /* 切歌时先输出短静音，减小突变爆音。 */
            s_switch_requested = false;
            (void)audio_silence(40U);
        }
    }
}

void app_main(void)
{
    const esp_reset_reason_t reset_reason = esp_reset_reason();
    if (s_wdt_trace_magic == WDT_TRACE_MAGIC && reset_reason == ESP_RST_INT_WDT) {
        ESP_LOGW(TAG, "Previous interrupt WDT stages: CPU0=%lu CPU1=%lu",
                 (unsigned long)s_wdt_trace_stage[0],
                 (unsigned long)s_wdt_trace_stage[1]);
    }
    s_wdt_trace_magic = WDT_TRACE_MAGIC;
    s_wdt_trace_stage[0] = 0U;
    s_wdt_trace_stage[1] = 0U;

    s_player_commands = xQueueCreate(16U, sizeof(player_command_t));
    s_display_updates = xQueueCreate(1U, sizeof(display_update_t));
    if (s_player_commands == NULL || s_display_updates == NULL) {
        ESP_LOGE(TAG, "Cannot allocate player/display queue");
        return;
    }
    ESP_ERROR_CHECK(button_init());

    const esp_err_t tft_error = tft_init();
    if (tft_error != ESP_OK) {
        ESP_LOGW(TAG,
                 "ST7789 unavailable on SCL=%d/SDA=%d: %s; audio will continue",
                 TFT_SCLK_GPIO, TFT_MOSI_GPIO, esp_err_to_name(tft_error));
    } else {
        const esp_err_t logo_error = tft_show_njupt_logo();
        if (logo_error != ESP_OK) {
            ESP_LOGW(TAG, "NJUPT logo failed: %s", esp_err_to_name(logo_error));
        }
        const esp_err_t loading_error = tft_show_loading(0U, SD_MOUNT_RETRY_COUNT);
        if (loading_error != ESP_OK) {
            ESP_LOGW(TAG, "Loading screen failed: %s", esp_err_to_name(loading_error));
        }
        gpio_set_level(TFT_BL_GPIO, 1);
    }

    const esp_err_t sd_error = sd_card_init_and_scan();
    if (sd_error != ESP_OK) {
        ESP_LOGW(TAG, "microSD unavailable: %s; player will continue",
                 esp_err_to_name(sd_error));
    }

    ESP_LOGI(TAG, "MAX98357: BCLK=%d LRC=%d DIN=%d",
             I2S_BCLK_GPIO, I2S_LRC_GPIO, I2S_DIN_GPIO);
    ESP_LOGI(TAG, "ST7789: SCL=%d SDA=%d RES=%d DC=%d BLK=%d",
             TFT_SCLK_GPIO, TFT_MOSI_GPIO, TFT_RST_GPIO, TFT_DC_GPIO, TFT_BL_GPIO);
    ESP_LOGI(TAG, "Initial volume: MUSIC=%u%% PIANO=%u%%; short BOOT switches mode, hold BOOT opens settings",
             (unsigned)PLAYER_VOLUME_PERCENT, (unsigned)PIANO_VOLUME_PERCENT);

    const esp_err_t speech_error = speech_init();
    s_voice_ready = speech_error == ESP_OK && s_speech.mn_data != NULL;
    s_voice_active = s_voice_ready;
    if (speech_error != ESP_OK) {
        ESP_LOGE(TAG, "ESP-SR init failed: %s; button playback remains available",
                 esp_err_to_name(speech_error));
    }

    if (s_tft_ready &&
        xTaskCreatePinnedToCore(display_task, "tft_display", DISPLAY_TASK_STACK_SIZE,
                                NULL, DISPLAY_TASK_PRIORITY, NULL,
                                DISPLAY_TASK_CORE) != pdPASS) {
        ESP_LOGW(TAG, "Cannot create TFT task; audio will continue without updates");
        const display_update_t fallback = {
            .song_index = s_song_index, .volume_percent = s_volume_percent,
            .player_started = true, .voice_ready = s_voice_ready,
        };
        tft_draw_status(&fallback);
    }
    if (xTaskCreatePinnedToCore(player_task, "music_player", PLAYER_TASK_STACK_SIZE,
                               NULL, PLAYER_TASK_PRIORITY, NULL,
                               PLAYER_TASK_CORE) != pdPASS) {
        ESP_LOGE(TAG, "Cannot create high-priority player task");
        return;
    }
    ESP_LOGI(TAG, "Tasks: player CPU%d/P%d, SR feed CPU%d/P%d, "
                  "SR detect CPU%d/P%d, TFT CPU%d/P%d",
             PLAYER_TASK_CORE, PLAYER_TASK_PRIORITY,
             SPEECH_FEED_TASK_CORE, SPEECH_FEED_TASK_PRIORITY,
             SPEECH_DETECT_TASK_CORE, SPEECH_DETECT_TASK_PRIORITY,
             DISPLAY_TASK_CORE, DISPLAY_TASK_PRIORITY);

    /* app_main 无需再占用 CPU0；后续状态只由各自任务维护。 */
    vTaskDelete(NULL);
}
